/* Google Sans Flex (variable weight), SIL OFL. Embedded so it loads from file:// and inside exported card images. */
window.CHECKAEO_FONT_CSS="@font-face{font-family:'Google Sans Flex';font-style:normal;font-weight:1 1000;font-display:swap;src:url(data:font/woff2;base64,) format('woff2-variations'),url(data:font/woff2;base64,) format('woff2');}";
(function(){var s=document.createElement('style');s.textContent=window.CHECKAEO_FONT_CSS;document.head.appendChild(s);})();
